            } // if joined row not null

            // Add objects for joined FormaRecepcion rows

            $key8 = FormaRecepcionPeer::getPrimaryKeyHashFromRow($row, $startcol8);
            if ($key8 !== null) {
                $obj8 = FormaRecepcionPeer::getInstanceFromPool($key8);
                if (!$obj8) {

                    $cls = FormaRecepcionPeer::getOMClass();

                    $obj8 = new $cls();
                    $obj8->hydrate($row, $startcol8);
                    FormaRecepcionPeer::addInstanceToPool($obj8, $key8);
                } // if obj8 loaded

                // Add the $obj1 (Factura) to the collection in $obj8 (FormaRecepcion)
                $obj8->addFactura($obj1);
            } // if joined row not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


