    /**
     * Selects a collection of Factura objects pre-filled with all related objects except Proveedor.
     *
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of Factura objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptProveedor(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(FacturaPeer::DATABASE_NAME);
        }

        FacturaPeer::addSelectColumns($criteria);
        $startcol2 = FacturaPeer::NUM_HYDRATE_COLUMNS;

        RegionalPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + RegionalPeer::NUM_HYDRATE_COLUMNS;

        PeriodoPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + PeriodoPeer::NUM_HYDRATE_COLUMNS;

        DependenciaPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + DependenciaPeer::NUM_HYDRATE_COLUMNS;

        FacturaEstadoPeer::addSelectColumns($criteria);
        $startcol6 = $startcol5 + FacturaEstadoPeer::NUM_HYDRATE_COLUMNS;

        FacturaTipoPeer::addSelectColumns($criteria);
        $startcol7 = $startcol6 + FacturaTipoPeer::NUM_HYDRATE_COLUMNS;

        FormaRecepcionPeer::addSelectColumns($criteria);
        $startcol8 = $startcol7 + FormaRecepcionPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(FacturaPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID, $join_behavior);

        $criteria->addJoin(FacturaPeer::PERIODO_ID, PeriodoPeer::PERIODO_ID, $join_behavior);

        $criteria->addJoin(FacturaPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID, $join_behavior);

        $criteria->addJoin(FacturaPeer::FACTURAESTADO_ID, FacturaEstadoPeer::FACTURAESTADO_ID, $join_behavior);

        $criteria->addJoin(FacturaPeer::FACTURATIPO_ID, FacturaTipoPeer::FACTURATIPO_ID, $join_behavior);

        $criteria->addJoin(FacturaPeer::FORMARECEPCION_ID, FormaRecepcionPeer::FORMARECEPCION_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseFacturaPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = FacturaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = FacturaPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = FacturaPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                FacturaPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined Regional rows

                $key2 = RegionalPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = RegionalPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = RegionalPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    RegionalPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (Factura) to the collection in $obj2 (Regional)
                $obj2->addFactura($obj1);

            } // if joined row is not null

                // Add objects for joined Periodo rows

                $key3 = PeriodoPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = PeriodoPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = PeriodoPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    PeriodoPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (Factura) to the collection in $obj3 (Periodo)
                $obj3->addFactura($obj1);

            } // if joined row is not null

                // Add objects for joined Dependencia rows

                $key4 = DependenciaPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = DependenciaPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = DependenciaPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    DependenciaPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Factura) to the collection in $obj4 (Dependencia)
                $obj4->addFactura($obj1);

            } // if joined row is not null

                // Add objects for joined FacturaEstado rows

                $key5 = FacturaEstadoPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = FacturaEstadoPeer::getInstanceFromPool($key5);
